import numpy as np
from collections import deque

def walk(steps, direction):
    if direction == 'north':
        return (0, steps)
    elif direction == 'south':
        return (0, -steps)
    elif direction == 'east':
        return (steps, 0)
    elif direction == 'west':
        return (-steps, 0)

def turn_right(direction):
    directions = 'north', 'east', 'south', 'west'
    return directions[(directions.index(direction) + 1) % 4]

def walk_forward(steps, direction):
    return walk(steps, direction)

def main():
    grid = np.zeros((10, 10))
    grid[0, 0] = 1
    x, y = 0, 0
    directions = deque(['north'] * 4)
    for _ in range(10):
        if directions[0] == 'north':
            x, y = walk_forward(3, directions[0])
            directions.rotate(-1)
        elif directions[0] == 'east':
            x, y = walk_forward(4, directions[0])
            directions.rotate(-1)
        elif directions[0] == 'south':
            x, y = walk_forward(2, directions[0])
            directions.rotate(-1)
        elif directions[0] == 'west':
            x, y = walk_forward(4, directions[0])
            directions.rotate(-1)
        directions.rotate(-1)
    directions.rotate(1)
    x, y = walk_forward(1, directions[0])
    x, y = walk_forward(2, directions[0])
    directions.rotate(-1)
    x, y = turn_right(directions[0])
    x, y = turn_right(directions[0])
    x, y = walk_forward(1, directions[0])
    x, y = walk_forward(2, directions[0])
    directions.rotate(-1)
    x, y = turn_right(directions[0])
    x, y = walk_forward(1, directions[0])
    print(x, y)

if __name__ == '__main__':
    main()
```

