import math

def turn_right(pos):
    return [(pos[1], -pos[0])] * 3 + [(pos[1], -pos[0]), (0, 1), (-pos[1], 0)]

def turn_left(pos):
    return [(pos[1], -pos[0]), (0, 1), (-pos[1], 0), pos]

def walk(steps, pos):
    return [(pos[0] + steps * pos[0], pos[1] + steps * pos[1])] * steps

def robot_path(steps, pos):
    for i in range(1, len(steps) + 1):
        if i % 2 == 1:
            pos = turn_right(steps[i - 1])(pos)
        else:
            pos = walk(steps[i - 1], pos)
    return pos

pos = (0, 0)
steps = [1, 3, 2, 3, 4, 0, 0, 2, 0, 3]
print(robot_path(steps, pos))
