import math

def rotate_left(n):
    # Rotate left by n steps
    return (n - 1) % 4

def rotate_right(n):
    # Rotate right by n steps
    return (n + 1) % 4

def step(n, direction):
    # Move n steps in the given direction
    if direction == 'north':
        return (0, n)
    elif direction == 'east':
        return (n, 0)
    elif direction == 'south':
        return (0, -n)
    elif direction == 'west':
        return (-n, 0)

# Robot starts at (0, 0), facing north
