direction = 'north'

instructions = [
    ('left', 1),
    ('left', 1),
    ('left', 1),
    ('forward', 3),
    ('forward', 2),
    ('left', 1),
    ('right', 1),
    ('left', 1),
    ('forward', 1),
    ('forward', 1)
]

for act, n in instructions:
    if act == 'left':
        direction = rotate_left(direction)
    elif act == 'right':
        direction = rotate_right(direction)
    elif act == 'forward':
        pos = step(n, direction)
    else:
        raise ValueError(f'Unknown action: {act}')

