from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def turn(self, turn):
        if turn == 'right':
            return 'left'
        return 'right'

    def walk(self, steps):
        for _ in range(steps):
            if self.turn == 'right':
                self.turn = 'left'
            elif self.turn == 'left':
                self.turn = 'right'

            if self.turn == 'right':
                self.y += 1
            elif self.turn == 'left':
                self.y -= 1

            if self.turn == 'right':
                self.x -= 1
            elif self.turn == 'left':
                self.x += 1

x, y = 0, 0
robot = Robot(x, y)
for i in range(1, 11):
    print(f"Step {i}: {robot.turn}")
    robot.walk(2)
    print(f"After step {i}: {robot.x}, {robot.y}")
