import math

def turn_right(heading):
    # Turn right by 90 degrees, 90 degrees = pi/2 radians
    return (heading[1], -heading[0])

def move_forward(steps, heading):
    # Move forward by steps, heading is a tuple (x, y)
    return (heading[0] * steps, heading[1] * steps)

def robot_instructions():
    # Initial position and heading
    pos = (0, 0)
    heading = (0, 1)  # north

    steps = [('forward', 2), ('forward', 4), ('turn', 1), ('forward', 1), ('forward', 2), ('turn', 1), ('forward', 1), ('forward', 4), ('forward', 3), ('forward', 4), ('forward', 4)]
    for act, n in steps:
        if act == 'forward':
            pos = move_forward(n, heading)
        elif act == 'turn':
            heading = turn_right(heading)
        else:
            raise Exception(f"Unknown action: {act}")
    return pos

