import math

def turn_right(a):
    return {'north': 'east', 'east': 'south', 'south': 'west', 'west': 'north'}[a]

def walk(steps):
    return [0, steps]

def move(a, b):
    return [a + b[0], a + b[1]]

def turn(a, b):
    if a == 'north':
        return turn_right(b)
    elif a == 'south':
        return turn_right(turn_right(b))
    elif a == 'east':
        return turn_right(turn_right(turn_right(b)))
    elif a == 'west':
        return turn_right(turn_right(turn_right(turn_right(b))))

