    if direction == 'east':
        for step in steps:
            x += step
    elif direction == 'north':
        for step in steps:
            y += step
    return x, y

x, y = 0, 0
instructions = [('forward', 1, 'north'), ('forward', 3, 'north'), ('forward', 2, 'east'), ('turn', 'left'), ('forward', 3, 'east'), ('forward', 3, 'east'), ('turn', 'right'), ('forward', 2, 'east'), ('forward', 2, 'east'), ('forward', 3, 'east')]
for command, n, direction in instructions:
    if command == 'forward':
        x, y = move(x, y, n, direction)
    elif command == 'turn':
        if direction == 'north':
            direction = 'west'
