from collections import deque

def robot_path(steps):
    current_position = np.array([0, 0])
    direction = np.array([0, 1])  # north
    instructions = deque(steps)

    while instructions:
        command = instructions.popleft()
        if command == 'forward':
            current_position += direction * 3
        elif command == 'turn left':
            direction = -direction
        elif command == 'turn right':
            direction = np.array([1, 0]) if direction == np.array([0, 1]) else np.array([0, -1])

    return tuple(current_position)

