import itertools

def get_directions():
    directions = ['N', 'L', 'N', 'E', 'N', 'L', 'N', 'E', 'L', 'L']
    return list(itertools.cycle(directions))

def turn_right(direction, steps):
    return (directions[(directions.index(direction) + 1) % 4], steps)

def turn_left(direction, steps):
    return (directions[(directions.index(direction) - 1) % 4], steps)

def walk(direction, steps):
    return (directions[(directions.index(direction) + 1) % 4], steps)

def get_final_position(steps):
    directions = get_directions()
    pos = (0, 0)
    for d, s in steps:
        if d == 'N':
            pos = (pos[0], pos[1] + s)
        elif d == 'E':
            pos = (pos[0] + s, pos[1])
        elif d == 'L':
            pos = turn_left(directions[0], s)
        elif d == 'R':
            pos = turn_right(directions[-1], s)
    return pos

