from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x, self.y = x, y
        self.direction = 'N'
        self.turns = deque()

    def walk(self, steps):
        for _ in range(steps):
            if self.direction == 'N':
                self.y += 1
            elif self.direction == 'S':
                self.y -= 1
            elif self.direction == 'E':
                self.x += 1
            elif self.direction == 'W':
                self.x -= 1

    def turn(self, direction):
        if direction == 'L':
            self.turns.append(direction)
        elif direction == 'R':
            self.turns.appendleft(direction)

    def execute(self, instructions):
        for instruction in instructions:
            if instruction == 'WALK':
                self.walk(int(input()))
            elif instruction == 'TURN':
                self.turn(input())
            elif instruction == 'END':
                self.turns.clear()

    def print_position(self):
        print((self.x, self.y))

    def get_final_position(self):
        self.execute('WALK WALK WALK WALK WALK WALK WALK TURN R L L L L L L L END')
        self.print_position()
        return self.x, self.y

