from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y
        self.directions = deque(['north', 'east', 'south', 'west'])

    def turn_left(self):
        self.directions.rotate(-1)

    def turn_right(self):
        self.directions.rotate(1)

    def move(self, n):
        if self.directions:
            direction = self.directions.pop()
            if direction == 'north':
                self.y += n
            elif direction == 'south':
                self.y -= n
            elif direction == 'east':
                self.x += n
            elif direction == 'west':
                self.x -= n

    def move_forward(self, n):
        self.move(n)

    def walk_forward(self, n):
        for _ in range(n):
            self.move_forward(1)

    def spin_clockwise(self, n):
        self.turn_right()
        self.move_forward(n)

    def spin_counterclockwise(self, n):
        self.turn_left()
        self.move_forward(n)

    def __str__(self):
        return f'({self.x}, {self.y})'

