import math

def turn_right(p, n):
    """Turn right by 90 degrees clockwise, then move forward 'n' steps."""
    if n < 0:
        n = -n
    else:
        n = -n
    p[0], p[1] = -p[1], p[0]

def turn_left(p, n):
    """Turn left by 90 degrees clockwise, then move forward 'n' steps."""
    if n < 0:
        n = -n
    else:
        n = -n
    p[0], p[1] = -p[1], -p[0]

def move_forward(p, n):
    """Move forward 'n' steps, updating the position."""
    p[0] += n * p[1]
    p[1] += n * p[0]

def process_instructions(instructions):
    """Process a sequence of instructions and return the final position."""
    x, y = 0, 0
    for instruction in instructions:
        if instruction == "right":
            turn_right((x, y), 2)
        elif instruction == "left":
            turn_left((x, y), 2)
        elif instruction == "forward":
            move_forward((x, y), 2)
        elif instruction == "left":
            turn_left((x, y), 2)
        elif instruction == "forward":
            move_forward((x, y), 2)
        elif instruction == "forward":
            move_forward((x, y), 2)
        elif instruction == "forward":
            move_forward((x, y), 3)
        elif instruction == "forward":
            move_forward((x, y), 1)
        elif instruction == "forward":
            move_forward((x, y), 4)
        elif instruction == "left":
            turn_left((x, y), 1)
        elif instruction == "forward":
            move_forward((x, y), 1)
    return (x, y)

