from collections import deque

def turn_right(d):
    return {0: 1, 1: 2, 2: 3, 3: 0}[d]

def walk(steps):
    return steps * (0, 1)

def process(n, d):
    for _ in range(n):
        d = turn_right(d)
        yield d

def move(n, d):
    for _ in range(n):
        yield d

def find_position(steps):
    grid = deque([(0, 0)])
    x, y = 0, 0
    d = 0
    for n, d in zip(process(steps[0], d), process(steps[1], d)):
        for step in move(n, d):
            grid.append(grid[-1] + step)
    return grid

def get_position():
    steps = [2, 1, 3, 1, 1, 2, 1, 2, 3, 1]
    return tuple(grid[-1] for grid in find_position(steps))

