import numpy as np
def turn_right(c, n):
    """Turn right. n is the number of steps to turn."""
    return c + np.array([-n, n])

def turn_left(c, n):
    """Turn left. n is the number of steps to turn."""
    return c + np.array([n, -n])

def walk(steps, c):
    """Walk forward 'steps' steps in direction 'c'."""
    return c + np.array(steps * np.array(c))

def main():
    x, y = 0, 0
    c = np.array([0, 1])
    instructions = [
        ('right', 1),
        ('forward', 3),
        ('turn', 2),
        ('turn', 2),
        ('left', 1),
        ('left', 1),
        ('forward', 2),
        ('left', 1),
        ('forward', 3),
        ('forward', 3),
    ]
    for act, n in instructions:
        if act == 'right':
            c = turn_right(c, n)
        elif act == 'left':
            c = turn_left(c, n)
        elif act == 'forward':
            c = walk(n, c)
        else:
            c += np.array(n)
    print((c[0], c[1]))
if __name__ == '__main__':
