import math

def turn_left(towards, steps):
    # Calculate the next position after turning left
    return (math.cos(math.radians(steps)), math.sin(math.radians(steps)))

def turn_right(towards, steps):
    # Calculate the next position after turning right
    return (math.cos(math.radians(-steps)), math.sin(math.radians(-steps)))

def walk(steps, towards, x, y):
    # Calculate the next position after walking forward
    return (x + steps * towards[0], y + steps * towards[1])

def position(steps, towards):
    x, y = 0, 0
    for i in range(steps):
        x, y = walk(i + 1, towards, x, y)
    return (x, y)

