from collections import deque

class Robot:
    def __init__(self, facing='n'):
        self.x = 0
        self.y = 0
        self.facing = facing

    def turn_right(self):
        if self.facing == 'n':
            self.facing = 'w'
        elif self.facing == 'w':
            self.facing = 's'
        elif self.facing == 's':
            self.facing = 'e'
        else:
            self.facing = 'n'

    def turn_left(self):
        if self.facing == 'n':
            self.facing = 'w'
        elif self.facing == 'w':
            self.facing = 's'
        elif self.facing == 's':
            self.facing = 'e'
        else:
            self.facing = 'n'

    def walk(self):
        if self.facing == 'n':
            self.y += 1
        elif self.facing == 'w':
            self.x -= 1
        elif self.facing == 's':
            self.y -= 1
        else:
            self.x += 1

    def move(self):
        self.turn_right()
        self.walk()
        self.turn_left()
        self.turn_left()
        self.turn_left()
        self.turn_right()
        self.walk()
        self.walk()
        self.walk()

    def print_position(self):
        print(f'x: {self.x}, y: {self.y}')

# Create a robot facing north
