    directions = []
    for i in itertools.cycle([0, 1, 2, 3]):
        directions.append((i, i))
    return directions

def rotate(directions, turn):
    if turn == 90:
        return directions[1::2], directions[0::2]
    if turn == 180:
        return directions[::-1], []
    if turn == 270:
        return directions[::2], directions[1::2]
    return directions, []

