def turn_right(direction):
    directions = ['north', 'east', 'south', 'west']
    return directions[(directions.index(direction) + 1) % 4]

def turn_left(direction):
    directions = ['north', 'east', 'south', 'west']
    return directions[(directions.index(direction) - 1) % 4]

def walk(steps, direction):
    return [direction, steps]

def move(steps, direction):
    steps -= 1
    if steps == 0:
        return direction, 0
    if direction == 'north':
        return walk(steps, 'east')
    elif direction == 'east':
        return walk(steps, 'south')
    elif direction == 'south':
        return walk(steps, 'west')
    else:
        return walk(steps, 'north')

def simulate(steps, direction, robot_position):
    for step in steps:
        direction, steps = move(steps, direction)
        robot_position = move(steps, direction)
    return robot_position

def final_position(steps, direction):
    initial_position = ('north', 0)
    final_position = simulate(steps, direction, initial_position)
    return final_position

