import math

def turn_left(r, d):
    if d == 'forward':
        d = 'right'
    else:
        d = 'forward'
    return d

def walk_forward(r, d, steps):
    for _ in range(steps):
        if d == 'forward':
            r[1] += 1
        else:
            r[0] += 1

def main():
    r = [0, 0]  # (x, y)
    d = 'forward'
    for _ in range(8):
        d = turn_left(r, d)
        walk_forward(r, d, 3)
    d = turn_left(r, d)
    walk_forward(r, d, 1)
    return r

if __name__ == "__main__":
    final_pos = main()
    print(final_pos)
