import itertools

def move(n, direction, position, orientation):
    if direction == 'forward':
        if orientation == 'north':
            return (position[0], position[1] + n)
        elif orientation == 'east':
            return (position[0] + n, position[1])
        else:
            raise ValueError("Invalid orientation")
    elif direction == 'right':
        if orientation == 'north':
            return (position[0] + n, position[1])
        elif orientation == 'east':
            return (position[0] + n, position[1] + n)
        else:
            raise ValueError("Invalid orientation")
    elif direction == 'left':
        if orientation == 'north':
            return (position[0], position[1] + n)
        elif orientation == 'east':
            return (position[0] - n, position[1])
        else:
            raise ValueError("Invalid orientation")
    else:
        raise ValueError("Invalid direction")

def follow_instructions(steps):
    position = (0, 0)
    orientation = 'north'
    for step in steps:
        direction, n = step
        for _ in range(n):
            position = move(n, direction, position, orientation)
            orientation = move(1, direction, orientation, 'north')
    return position

