import math

def turn_right(direction):
    directions = ['north', 'east', 'south', 'west']
    return directions[(directions.index(direction) + 1) % 4]

def turn_left(direction):
    directions = ['north', 'east', 'south', 'west']
    return directions[(directions.index(direction) - 1) % 4]

def walk(steps, direction):
    steps, direction = int(steps), direction
    x, y = 0, 0
    for i in range(steps):
        if direction == 'north':
            y += 1
        elif direction == 'east':
            x += 1
        elif direction == 'south':
            y -= 1
        elif direction == 'west':
            x -= 1
    return x, y

def simulate(robot):
    directions = ['north', 'east', 'south', 'west']
    robot['x'], robot['y'] = 0, 0
    robot['direction'] = 'north'
    steps = 0
    for act in robot['instructions']:
        if act == 'walk':
            steps += 1
            x, y = walk(steps, robot['direction'])
        elif act == 'turn':
            if robot['direction'] == 'north':
                robot['direction'] = 'east'
            elif robot['direction'] == 'east':
                robot['direction'] = 'south'
            elif robot['direction'] == 'south':
                robot['direction'] = 'west'
            elif robot['direction'] == 'west':
                robot['direction'] = 'north'
    return robot['x'], robot['y']

robot = {'instructions': ['walk', 'walk', 'turn', 'turn', 'walk', 'walk', 'walk', 'walk', 'turn', 'turn', 'walk']}
print(simulate(robot))
