import math

def turn_right(rotation):
    return 1 if rotation == 0 else -1 if rotation == 3 else 0

def turn_left(rotation):
    return -1 if rotation == 0 else 1 if rotation == 3 else 0

def walk(steps, direction):
    return steps * direction

def final_position(steps):
    x, y = 0, 0
    rotation = 0
    for i in range(steps):
        if i % 2 == 0:
            x += walk(steps//2, turn_right(rotation))
            y += walk(steps//2, turn_left(rotation))
        else:
            x += walk(steps//2, turn_left(rotation))
            y += walk(steps//2, turn_right(rotation))
        rotation = (rotation + 1) % 4
    return (x, y)

print(final_position(20))
