            if facing == 'north':
                facing = 'west'
            elif facing == 'east':
                facing = 'south'
            elif facing == 'south':
                facing = 'east'
            elif facing == 'west':
                facing = 'north'
        elif action == 'turn right':
            if facing == 'north':
                facing = 'east'
            elif facing == 'east':
                facing = 'south'
            elif facing == 'south':
                facing = 'west'
            elif facing == 'west':
                facing = 'north'
