    for _ in range(steps):
        if facing == 'n':
            y += 1
        elif facing == 'w':
            x -= 1
        elif facing == 's':
            y -= 1
        elif facing == 'e':
            x += 1
    return x, y

def find_final_position(grid, instructions):
    x, y = 0, 0
    facing = 'n'
    for instruction in instructions:
        if instruction == 1:
            x, y = walk_forward(grid, facing, 1)
        elif instruction == 2:
            facing = turn_left(grid, facing)
        elif instruction == 3:
            facing = turn_right(grid, facing)
        elif instruction == 4:
            x, y = walk_forward(grid, facing, 4)
        elif instruction == 5:
            x, y = walk_forward(grid, facing, 2)
        elif instruction == 6:
            facing = turn_left(grid, facing)
        elif instruction == 7:
            x, y = walk_forward(grid, facing, 3)
        elif instruction == 8:
            x, y = walk_forward(grid, facing, 4)
        elif instruction == 9:
            x, y = walk_forward(grid, facing, 2)
        elif instruction == 10:
            x, y = walk_forward(grid, facing, 3)

    return x, y

