import math

def turn_right(x, y):
    """Turns the robot 90 degrees counterclockwise and returns its new position."""
    return (-y, x)

def turn_left(x, y):
    """Turns the robot 90 degrees clockwise and returns its new position."""
    return (y, -x)

def walk_forward(x, y, steps):
    """Walks forward 'steps' and returns its new position."""
    for _ in range(steps):
        x, y = x + 1, y + (1 if y < 0 else -1)
    return x, y

def move_robot(steps):
    """Moves the robot according to the instructions."""
    x, y = 0, 0
    for i in range(steps):
        if i in {0, 2, 4, 6, 8}:
            x, y = walk_forward(x, y, steps // 2)
        elif i in {1, 3, 5, 7, 9}:
            x, y = walk_forward(x, y, steps // 2)
        elif i == 10:
            x, y = turn_left(x, y)
        else:
            x, y = turn_right(x, y)
        yield x, y

def final_position(steps):
    """Returns the final position of the robot."""
    return list(move_robot(steps))[-1]

