from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y
        self.directions = deque(['north', 'east', 'south', 'west'])

    def turn_left(self):
        self.directions.rotate(-1)

    def turn_right(self):
        self.directions.rotate(1)

    def walk(self, n):
        if n > 0:
            if self.directions[-1] == 'north':
                self.y += n
            elif self.directions[-1] == 'east':
                self.x += n
            elif self.directions[-1] == 'south':
                self.y -= n
            elif self.directions[-1] == 'west':
                self.x -= n
        elif n < 0:
            if self.directions[-1] == 'north':
                self.y -= n
            elif self.directions[-1] == 'east':
                self.x -= n
            elif self.directions[-1] == 'south':
                self.y += n
            elif self.directions[-1] == 'west':
                self.x += n

    def move(self, n, direction):
        if direction == 'right':
            self.turn_right()
        elif direction == 'left':
            self.turn_left()
        self.walk(n)

    def __repr__(self):
        return f'({self.x}, {self.y})'

