import math

def turn_left(grid, i):
    # Assuming grid is circular and i is between 0 and 3
    i = (i + 1) % 4
    return i

def turn_right(grid, i):
    # Assuming grid is circular and i is between 0 and 3
    i = (i - 1) % 4
    return i

def walk_forward(grid, i, steps):
    # Assuming grid is circular and i is between 0 and 3
    i = (i + steps) % 4
    return i

def get_robot_position(steps):
    x, y = 0, 0
    i = 0
    for step in steps:
        if step[0] == 'left':
            i = turn_left(i, 0)
        elif step[0] == 'right':
            i = turn_right(i, 0)
        elif step[0] == 'forward':
            i = walk_forward(i, 0, step[1])
        else:
            raise ValueError("Invalid step type: " + step[0])
        if step[0] == 'left':
            i = turn_left(i, 1)
        elif step[0] == 'right':
            i = turn_right(i, 1)
        elif step[0] == 'forward':
