import math

def turn_right(t):
    return 90 - t % 360 if t % 360 != 180 else 90 - t % 360

def turn_left(t):
    return 90 + t % 360 if t % 360 != 180 else 90 + t % 360

def walk_forward(t, steps):
    dx, dy = 0, 1
    for _ in range(steps):
        if t % 360 == 180:
            dx, dy = -dy, dx
        else:
            dx, dy = dx, -dy
        yield (t, (dx, dy))

def move(t, d, steps):
    if steps == 0:
        return
    yield (t, d)
    yield from walk_forward(t, steps)

def go_forward(steps):
    yield from walk_forward(0, steps)

def go(steps):
    yield from move(0, (0, 1), steps)

def turn(n):
    yield from go(steps=n)

def main():
    x, y = 0, 0
    for _ in range(10):
        x, y = x + 4, y + 4
        print(f"x: {x}, y: {y}")
