        elif step == 'forward' * 1:
            x, y = move_forward(step, orientation)
        elif step == 'forward' * 3:
            x, y = move_forward(step, orientation)
        elif step == 'forward' * 4:
            x, y = move_forward(step, orientation)
        elif step == 'left':
            orientation = turn_left(orientation)
        elif step == 'right':
