from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def turn(self, direction):
        if direction == 'right':
            self.turn_right()
        elif direction == 'left':
            self.turn_left()

    def turn_right(self):
        if self.y > 0:
            self.y -= 1
        elif self.y < 0:
            self.y += 1
        else:
            self.y = 0

    def turn_left(self):
        if self.y > 0:
            self.y += 1
        elif self.y < 0:
            self.y -= 1
        else:
            self.y = 0

    def walk(self, steps):
        self.x += steps
        self.y += steps

    def move(self, instruction):
        if instruction == 'right':
            self.turn_right()
        elif instruction == 'left':
            self.turn_left()
        elif instruction == 'forward':
            self.walk(steps)
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

    def __str__(self):
        return f"({self.x}, {self.y})"

