import math

def turn_right(turns):
    """Turn right by the number of turns given."""
    directions = ['n', 'e', 's', 'w']
    new_turns = 0
    for i in range(turns):
        new_turns += 1
        new_turns %= len(directions)
    return directions[new_turns]

def move(steps):
    """Move forward the number of steps given."""
    x, y = 0, 0
    for i in range(steps):
        if i % 2 == 0:
            y += 1
        else:
            x += 1
    return x, y

def solve(steps, instructions):
    """Simulate the robot following the given instructions."""
    robot = (0, 0)
    facing = 0  # 0: north, 1: east, 2: south, 3: west
    for i in range(1, instructions + 1):
        if i % 2 == 0:
            steps += 1
            facing = (facing + 1) % 4
        else:
            steps += 1
            facing = (facing - 1) % 4
        if facing == 2:
            facing = 3
        if facing == 3:
            facing = 2
        if facing == 0:
            facing = 1
        if facing == 1:
            facing = 0
        if facing == 0:
            x, y = move(steps)
        else:
            steps += 1
            x, y = move(steps)
    return x, y

final_position = solve(10, 8)
