from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y
        self.directions = deque(['north', 'east', 'south', 'west'])

    def turn_right(self):
        self.directions.rotate(-1)

    def turn_left(self):
        self.directions.rotate(1)

    def walk_forward(self, n=1):
        direction = self.directions.popleft()
        for _ in range(n):
            if direction == 'north':
                self.y += 1
            elif direction == 'east':
                self.x += 1
            elif direction == 'south':
                self.y -= 1
            elif direction == 'west':
                self.x -= 1

    def __repr__(self):
        return f'({self.x}, {self.y})'

    def final_position(self):
        return self.x, self.y

