def turn_left(tup, angle):
    angle += 180
    while angle >= 360:
        angle -= 360
    return tup[angle % 360]

def turn_right(tup, angle):
    angle -= 180
    while angle < 0:
        angle += 360
    return tup[angle % 360]

def walk_forward(tup, steps):
    return tuple(steps * tup)

def main():
