    for i in range(1, 11):
        if i % 2 == 1:
            direction = 'left'
            steps = 3
        else:
            direction = 'right'
            steps = 2
        x, y = walk_forward((x, y), steps), turn_left((x, y), direction)
    return (x, y)

print(main())
