from collections import deque

def turn_right():
    return [(0, 1), (1, 0), (0, -1), (-1, 0)][0]

def turn_left():
    return [(0, 1), (1, 0), (0, -1), (-1, 0)][1]

def walk(steps):
    return tuple(map(sum, zip(steps, (0, 1, 0, -1))))

def robot_instructions():
    position = (0, 0)
    facing = (0, 1)  # North
    steps = deque([4, 2, 2, 4, 2, 2, 2, 2, 2, 2, 2], maxlen=10)

    for _ in range(10):
        if facing == (0, 1):
            steps.rotate(1)
            facing = turn_right()
        elif facing == (1, 0):
            steps.rotate(2)
            facing = turn_left()
        elif facing == (0, -1):
            steps.rotate(3)
            facing = turn_right()
        elif facing == (-1, 0):
            steps.rotate(4)
            facing = turn_left()

        position = walk(steps.popleft())

    return position

