import math

def turn_right(angle):
    return 90 - angle % 360

def turn_left(angle):
    return 90 + angle % 360

def walk(steps, direction):
    x, y = 0, 0
    for _ in range(steps):
        if direction == 'n':
            y += 1
        elif direction == 's':
            y -= 1
        elif direction == 'e':
            x += 1
        elif direction == 'w':
            x -= 1
    return x, y

def main():
    # Robot starts at (0, 0), facing north
    initial_position = (0, 0)
    current_position = initial_position
    current_direction = 'n'

    for instruction in [('n', 4), ('r', 0), ('n', 4), ('r', 0), ('r', 90), ('n', 3), ('r', 0), ('n', 2), ('l', 180)]:
        if instruction[0] == 'n':
            current_position = walk(instruction[1], current_direction)
        elif instruction[0] == 's':
            current_position = walk(instruction[1], turn_right(current_direction))
        elif instruction[0] == 'e':
            current_position = walk(instruction[1], turn_right(current_direction))
        elif instruction[0] == 'w':
            current_position = walk(instruction[1], turn_right(current_direction))
        current_direction = instruction[1]

    print(current_position)

if __name__ == "__main__":
