from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def turn_right(self):
        self.turn = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[self.turn]

    def turn_left(self):
        self.turn = {'N': 'W', 'E': 'N', 'S': 'E', 'W': 'S'}[self.turn]

    def walk(self, n):
        if n == 0:
            return
        if n > 0:
            if self.turn == 'N':
                self.y += n
            elif self.turn == 'S':
                self.y -= n
            elif self.turn == 'E':
                self.x += n
            elif self.turn == 'W':
                self.x -= n
        if n < 0:
            if self.turn == 'N':
                self.y -= n
            elif self.turn == 'S':
                self.y += n
            elif self.turn == 'E':
                self.x -= n
            elif self.turn == 'W':
                self.x += n

def run():
    r = Robot()
    for i in range(10):
        if i < 5:
            r.turn_right()
        else:
            r.turn_left()
        if i < 5:
            r.walk(2)
        else:
            r.walk(4)
    return r.x, r.y

print(run())
```

