import math

def turn_left(degrees):
    # Turn left by 90 degrees, incrementing by 90 degrees until we reach the next direction
    return (90, degrees % 90)

def turn_right(degrees):
    # Turn right by 90 degrees, decrementing by 90 degrees until we reach the previous direction
    return (90, degrees % 90 + 90)

def walk_forward(steps, direction):
    # Walk forward a certain number of steps in a given direction, returning the new position
    x, y = 0, 0
    for _ in range(steps):
        if direction == 90:
            y += 1
        else:
            x += 1
    return (x, y)

