        ('walk forward 2 steps', 1),  # walk forward 2 steps
        ('walk forward 1 step', 1),  # walk forward 1 step
        ('walk forward 1 step', 1),  # walk forward 1 step
        ('walk forward 1 step', 1),  # walk forward 1 step
        ('turn left', 1),  # turn left
        ('turn right', 1),  # turn right
        ('walk forward 1 step', 1),  # walk forward 1 step
        ('walk forward 4 steps', 1)  # walk forward 4 steps
    ]

