import math

def turn_right(tup, deg):
    """Turns right by the specified angle and returns the new position."""
    deg = 360 - deg
    return (tup[0] + math.cos(math.radians(deg)), tup[1] + math.sin(math.radians(deg)))

def turn_left(tup, deg):
    """Turns left by the specified angle and returns the new position."""
    deg = 360 - deg
    return (tup[0] + math.cos(math.radians(deg)), tup[1] + math.sin(math.radians(deg)))

def walk(tup, dist):
    """Walks forward the specified distance and returns the new position."""
    return (tup[0] + dist, tup[1])

def move_robot(steps):
    """Moves the robot in the specified instructions."""
    positions = []
    positions.append((0, 0))
    for step in steps:
        if step == 'turn right':
            positions.append(turn_right(positions[-1], 90))
        elif step == 'turn left':
            positions.append(turn_left(positions[-1], 90))
        elif step == 'walk forward 4 steps':
            positions.append(walk(positions[-1], 4))
        elif step == 'walk forward 1 step':
            positions.append(walk(positions[-1], 1))
        elif step == 'walk forward 2 steps':
            positions.append(walk(positions[-1], 2))
        elif step == 'walk forward 3 steps':
            positions.append(walk(positions[-1], 3))
        elif step == 'walk forward 2 steps':
            positions.append(walk(positions[-1], 2))
        elif step == 'walk forward 1 step':
            positions.append(walk(positions[-1], 1))
        elif step == 'turn around':
            positions.append(turn_left(positions[-1], 180))
    return positions

