directions = ['N', 'R', 'L', 'F2', 'F4', 'L', 'F2', 'F3', 'F1', 'R']
def turn_right(direction):
    return directions[(directions.index(direction) + 1) % len(directions)]
def turn_left(direction):
    return directions[(directions.index(direction) - 1) % len(directions)]
def walk_forward(direction, steps):
    steps = steps % len(directions)
    for _ in range(steps):
        if direction == 'N':
            yield 0, 1
        elif direction == 'S':
            yield 0, -1
        elif direction == 'E':
            yield 1, 0
        elif direction == 'W':
            yield -1, 0

def move_robot(steps, directions):
    pos = (0, 0)
    for direction in directions:
        if direction == 'turn':
            continue
        for x, y in walk_forward(direction, steps):
            pos = (pos[0] + x, pos[1] + y)
    return pos
