from collections import deque

def turn_left():
    return lambda d: (d[0], -d[1])

def turn_right():
    return lambda d: (-d[0], d[1])

def walk(n):
    return lambda d: (d[0] * n, d[1] * n)

def move():
    return lambda d: (d[0], d[1])

def instructions():
    return deque([
        turn_left(),  # turn left
        turn_right(), # turn around
        turn_right(), # turn around
        turn_left(),  # turn left
        turn_left(),  # turn left
        walk(2),      # walk forward 2 steps
        walk(2),      # walk forward 2 steps
        turn_right(), # turn right
        walk(1),      # walk forward 1 step
        turn_right()   # turn right
    ])

def robot():
    d = (0, 1)  # start facing north
    for instruction in instructions():
        d = instruction(d)
    return d

