from collections import deque

class Robot:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y
        self.directions = deque(['north', 'east', 'south', 'west'])

    def turn_left(self):
        self.directions.rotate(-1)

    def turn_right(self):
        self.directions.rotate(1)

    def walk_forward(self, steps):
        for _ in range(steps):
            if self.directions[0] == 'north':
                self.y += 1
            elif self.directions[0] == 'east':
                self.x += 1
            elif self.directions[0] == 'south':
                self.y -= 1
            elif self.directions[0] == 'west':
                self.x -= 1

    def execute_instructions(self, instructions):
        for instruction in instructions:
            if instruction == 'north':
                self.directions.rotate(-1)
            elif instruction == 'east':
                self.directions.rotate(1)
            elif instruction == 'south':
                self.directions.rotate(1)
            elif instruction == 'west':
                self.directions.rotate(-1)
            elif instruction == 'left':
                self.turn_left()
            elif instruction == 'right':
                self.turn_right()
            elif instruction == 'walk forward':
                self.walk_forward(1)
            elif instruction == 'turn around':
                self.turn_left()
                self.turn_left()
            elif instruction == 'walk forward 2':
                self.walk_forward(2)
            elif instruction == 'walk forward 1':
                self.walk_forward(1)
            elif instruction == 'walk forward 1 step':
                self.walk_forward(1)
            elif instruction == 'walk forward 2 steps':
                self.walk_forward(2)

# Example usage
