    return (direction - 1) % 4

def move(steps, direction):
    if direction == 0:  # north
        return (steps, 0)
    elif direction == 1:  # east
        return (0, steps)
    elif direction == 2:  # south
        return (-steps, 0)
    elif direction == 3:  # west
        return (0, -steps)

