    steps = 0
    positions = [(0, 0)]
    for step in range(1, 11):
        if step == 1 or step == 3 or step == 5 or step == 7:
            direction = rotate_left(direction)
        steps, direction = move(steps, direction)
        positions.append((steps, direction))
    return tuple(positions[-1])

