    steps = [(1, 1), (3, 3), (4, 4), (2, 2), (1, 1), (1, 3), (1, 4), (1, 2), (1, 1), (1, 1), (1, 3)]
    for i in range(1, len(steps)):
        steps[i] = steps[i - 1] + steps[i]
    for (dx, dy), steps in zip(steps, steps[1:]):
        x, y = x + dx * steps, y + dy * steps
    return x, y

