import math

def turn_right(dx, dy):
    dx, dy = dy, -dx

def turn_left(dx, dy):
    dx, dy = -dy, dx

def walk(steps):
    dx, dy = 0, 1
    for _ in range(steps):
        dx, dy = dy, -dx
        yield dx, dy

def solve():
    position = (0, 0)
    direction = (0, 1)
    for _ in range(10):
        direction = turn_right(direction[0], direction[1])
        dx, dy = direction[0], direction[1]
        for _ in range(1 + sum(map(abs, direction))):
            position = (position[0] + dx, position[1] + dy)
            direction = turn_right(direction[0], direction[1])
    return position

print(solve())
